        auth.pbNonce=packet.nonce.data(); auth.cbNonce=12; auth.pbTag=packet.tag.data(); auth.cbTag=16;
        auth.pbAuthData=const_cast<PUCHAR>(aad.data()); auth.cbAuthData=(ULONG)aad.size();
